import { cn } from '@/lib/utils';
import DOMPurify from 'dompurify';

// ─── Types ────────────────────────────────────────────────────────────────────

export type ButtonVariant = 'default' | 'secondary' | 'outline' | 'ghost' | 'link' | 'destructive';
export type ButtonSize = 'default' | 'xs' | 'sm' | 'lg' | 'icon' | 'icon-xs' | 'icon-sm' | 'icon-lg';

export type ButtonOptions = {
  variant?: ButtonVariant;
  size?: ButtonSize;
  label?: string;
  ariaLabel?: string;
  ariaBusy?: boolean;
  ariaInvalid?: boolean;
  disabled?: boolean;
  type?: 'button' | 'submit' | 'reset';
  onClick?: (e: MouseEvent) => void;
  class?: string;
  children?: HTMLElement | string;
};

// ─── btnClass ─────────────────────────────────────────────────────────────────
//
// Retorna a lista de classes .nds-button-* aplicáveis. Sempre inclui .nds-button
// (base) + variante + (opcional) modificador de tamanho/ícone.
//
// Exemplos:
//   btnClass('default', 'default')  → 'nds-button nds-button-default'
//   btnClass('outline', 'sm')       → 'nds-button nds-button-sm nds-button-outline'
//   btnClass('ghost',   'icon-lg')  → 'nds-button nds-button-icon-lg nds-button-ghost'
//
// `default` não tem classe de tamanho: o dimensionamento base vive em
// `.nds-button`. Os demais são modificadores.

export function btnClass(variant: ButtonVariant | string = 'default', size: ButtonSize | string = 'default'): string {
  const base = 'nds-button';
  const sizeClass =
    size === 'icon'    ? 'nds-button-icon' :
    size === 'icon-xs' ? 'nds-button-icon-xs' :
    size === 'icon-sm' ? 'nds-button-icon-sm' :
    size === 'icon-lg' ? 'nds-button-icon-lg' :
    size === 'xs'      ? 'nds-button-xs' :
    size === 'sm'      ? 'nds-button-sm' :
    size === 'lg'      ? 'nds-button-lg' :
                         '';
  const variantClass = `nds-button-${variant}`;
  return [base, sizeClass, variantClass].filter(Boolean).join(' ');
}

// ─── createButton ─────────────────────────────────────────────────────────────

export function createButton(options: ButtonOptions): HTMLButtonElement {
  const { variant = 'default', size = 'default', label, ariaLabel, disabled, type = 'button', onClick, children } = options;

  const el = document.createElement('button');
  el.type = type;
  el.className = cn(btnClass(variant, size), options.class);

  if (label) el.textContent = label;
  if (ariaLabel) el.setAttribute('aria-label', ariaLabel);
  if (options.ariaBusy) el.setAttribute('aria-busy', 'true');
  if (options.ariaInvalid) el.setAttribute('aria-invalid', 'true');
  if (disabled) el.disabled = true;

  if (children) {
    if (typeof children === 'string') {
      // PATCH: security — DOMPurify.sanitize obrigatório em innerHTML (ver guideline 09-seguranca-xss.md)
      el.innerHTML = DOMPurify.sanitize(children);
    } else {
      el.appendChild(children);
    }
  }

  if (onClick) el.addEventListener('click', onClick);

  return el;
}

// ─── Icons ────────────────────────────────────────────────────────────────────

import { Plus, Trash2, Pencil, ChevronRight, Download, Loader2, X } from 'lucide';

export type ButtonIconKind = 'plus' | 'trash' | 'pencil' | 'chevron-right' | 'download' | 'loader' | 'x';

type LucideIconNode = [string, Record<string, string>];

const BUTTON_ICON_MAP: Record<ButtonIconKind, LucideIconNode[]> = {
  'plus':          Plus         as unknown as LucideIconNode[],
  'trash':         Trash2       as unknown as LucideIconNode[],
  'pencil':        Pencil       as unknown as LucideIconNode[],
  'chevron-right': ChevronRight as unknown as LucideIconNode[],
  'download':      Download     as unknown as LucideIconNode[],
  'loader':        Loader2      as unknown as LucideIconNode[],
  'x':             X            as unknown as LucideIconNode[],
};

export type ButtonIconSize = 'sm' | 'md' | 'lg';

export function createButtonIcon(
  kind: ButtonIconKind,
  options: { size?: ButtonIconSize; spin?: boolean; className?: string } = {},
): SVGSVGElement {
  const { size = 'md', spin, className } = options;
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  // Classes próprias .nds-* — independentes de qualquer framework CSS e de cascade externa.
  // .nds-button-icon-svg dá width/height base (1rem); modificador -<size> ajusta.
  svg.setAttribute(
    'class',
    cn('nds-button-icon-svg', `nds-button-icon-svg-${size}`, spin && 'nds-spin', className),
  );

  for (const [tag, attrs] of BUTTON_ICON_MAP[kind]) {
    const child = document.createElementNS('http://www.w3.org/2000/svg', tag);
    for (const [k, v] of Object.entries(attrs)) child.setAttribute(k, v);
    svg.appendChild(child);
  }
  return svg;
}

/*
 * ─── nds-button ───────────────────────────────────────────────────────────────
 * Componente standalone — zero dependência externa de CSS.
 * Consome apenas custom properties já definidas em tokens.css + themes/*.css.
 *
 * A11Y — WCAG 1.4.4 (Resize Text 200%):
 * Sem `height` fixo. Altura final é resultado de padding-block + line-height,
 * de modo que o button cresça proporcionalmente ao tamanho de fonte do navegador
 * (ex: zoom textual, settings → font size). NUNCA reintroduzir `height` nem
 * `min-height` em pixels fixos.
 *
 * Tokens de cor: --primary, --primary-foreground, --secondary, --secondary-foreground,
 *                --accent, --accent-foreground, --destructive, --destructive-foreground,
 *                --background, --foreground, --input, --ring, --border
 * Tokens de spacing: --spacing-* (grid 8: múltiplos/divisores de 8 apenas)
 * Tokens de raio: --radius-button
 * Tokens de tipografia: --font-family
 *
 * Variantes: default (primary), secondary, outline, ghost, link, destructive
 * Tamanhos: sm, default (padrão), lg + icon-only equivalentes
 *
 * Estados: :hover, :focus-visible, :disabled, [aria-pressed="true"], [aria-invalid="true"]
 * Dark: .dark .nds-button-* (combina via cascade)
 */

/* ── Base (todas as variantes e tamanhos compartilham) ─────────────────────── */
.nds-button {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-2);
  padding-inline: var(--spacing-4);
  padding-block: var(--spacing-2);
  border: 0 solid transparent;
  border-radius: var(--radius-button);
  background: transparent;
  color: inherit;
  font-family: var(--font-family, inherit);
  font-size: var(--text-control);                          /* 14px — text-sm */
  line-height: 1.25;                            /* unitless — escala com font-size */
  font-weight: var(--font-weight-medium, 500);
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
  outline: none;
  /* `transform` sai do lote: cor e sombra querem chegar rápido e parar
   * (`--ease-standard`), a escala quer mola. `--ease-spring` passa de 1 e volta,
   * que é o que dá a sensação de física do gesto — com 120ms o overshoot não
   * tem espaço para acontecer, daí `--duration-base`. */
  transition: background-color var(--duration-fast) var(--ease-standard),
              color var(--duration-fast) var(--ease-standard),
              border-color var(--duration-fast) var(--ease-standard),
              box-shadow var(--duration-fast) var(--ease-standard),
              opacity var(--duration-fast) var(--ease-standard),
              transform var(--duration-base) var(--ease-spring);
  -webkit-user-select: none;
  user-select: none;
}

/* SVG children — usam classes específicas para garantir tamanho mesmo quando
 * o componente é renderizado em contextos com cascade hostil (ex: emotion-css
 * do Storybook). Dimensões em rem (escalam com font-size do <html>) e não em
 * em (que dependeria do font-size do button, vulnerável a sobrescrita). */
.nds-button > svg,
.nds-button-icon-svg {
  pointer-events: none;
  flex-shrink: 0;
  width: 1rem;                                  /* 16px — default */
  height: 1rem;
}
.nds-button-icon-svg-sm { width: 0.875rem; height: 0.875rem; } /* 14px */
.nds-button-icon-svg-md { width: 1rem;     height: 1rem;     } /* 16px (default explícito) */
.nds-button-icon-svg-lg { width: 1.25rem;  height: 1.25rem;  } /* 20px */

/* Quando o button tem ícone (qualquer SVG filho direto), reduz padding lateral */
.nds-button:has(> svg) {
  padding-inline: var(--spacing-2);
}

/* ── Estados ───────────────────────────────────────────────────────────────── */
.nds-button:focus-visible {
  box-shadow: 0 0 0 2px hsl(var(--background)), 0 0 0 5px hsl(var(--ring) / 0.5);
}
.nds-button:disabled,
.nds-button[aria-disabled="true"] {
  pointer-events: none;
  opacity: 0.5;
}
.nds-button[aria-invalid="true"] {
  box-shadow: 0 0 0 2px hsl(var(--background)), 0 0 0 5px hsl(var(--destructive) / 0.4);
}
/* O anel de estado inválido é PERMANENTE — não some quando o elemento perde o
 * foco — e era declarado depois do `:focus-visible` com a mesma
 * especificidade. Resultado: focar um elemento inválido não mudava nada na
 * tela, e com vários inválidos na página não dava para saber qual estava em
 * foco. WCAG 2.4.7 (Focus Visible, AA).
 *
 * Os dois anéis convivem: o destrutivo por dentro, o de foco por fora. Mesmo
 * remédio já aplicado no `toggle`, onde o defeito foi medido primeiro. */
.nds-button[aria-invalid="true"]:focus-visible {
  box-shadow: 0 0 0 2px hsl(var(--background)), 0 0 0 5px hsl(var(--destructive) / 0.4), 0 0 0 7px hsl(var(--ring) / 0.5);
}


/* ── Tamanhos ──────────────────────────────────────────────────────────────────
 * Diferenciados por font-size + padding-block (não por height).
 * Texto e altura crescem juntos quando o usuário aumenta o tamanho da fonte. */
/* Escala vertical (grid 8 estrito — múltiplos/divisores de 8):
 *   sm:      padding-block 4 + 12×1.25 = ~23px
 *   default: padding-block 8 + 14×1.25 = ~33.5px
 *   lg:      padding-block 8 + 16×1.25 = ~36px
 *
 * lg diferencia de default pelo font-size (16 vs 14). sm reduz padding + font. */
.nds-button-sm {
  gap: var(--spacing-2);
  padding-inline: var(--spacing-4);
  padding-block: var(--spacing-1);
  font-size: var(--text-control-sm);                           /* 12px */
}
.nds-button-sm:has(> svg) {
  padding-inline: var(--spacing-2);
}
.nds-button-lg {
  gap: var(--spacing-2);
  padding-inline: var(--spacing-6);
  padding-block: var(--spacing-2);
  font-size: var(--text-control-lg);                              /* 16px */
}
.nds-button-lg:has(> svg) {
  padding-inline: var(--spacing-4);
}
/* xs — menor que sm: mesma fonte 12px, padding-block mínimo (2px, divisor de 8).
 * Mantém a regra WCAG 1.4.4: altura resultante de padding + line-height. */
.nds-button-xs {
  gap: var(--spacing-1);
  padding-inline: var(--spacing-2);
  padding-block: 0.125rem;                      /* 2px */
  font-size: var(--text-control-sm);                           /* 12px */
}
.nds-button-xs:has(> svg) {
  padding-inline: var(--spacing-1);
}
.nds-button-xs > svg,
.nds-button-xs .nds-button-icon-svg { width: 0.75rem; height: 0.75rem; }

/* Icon-only (quadrado) — sem texto. width/height explícitos em rem garantem
 * tamanho previsível em qualquer contexto (não dependem de font-size do
 * componente nem de cascade externa). Como não há texto, height fixo aqui
 * não viola a regra WCAG 1.4.4 — não existe texto a ser cortado.
 * O ícone interno escala via classes .nds-button-icon-svg-* aplicadas pela
 * factory, independentes do font-size do botão. */
.nds-button-icon,
.nds-button-icon-xs,
.nds-button-icon-sm,
.nds-button-icon-lg {
  padding: 0;
}
/* O quadrado lê a escada --size-*, que tem valor por densidade. Antes eram rem
 * cravados: o botão de ícone era a única peça que não encolhia no tema
 * condensado nem crescia no confortável, e ninguém via porque o número batia
 * com o da densidade padrão. */
.nds-button-icon-xs {
  width: var(--size-xs);                        /* 24px no tema padrão */
  height: var(--size-xs);
}
.nds-button-icon-xs > svg { width: 0.75rem; height: 0.75rem; }
.nds-button-icon-sm {
  width: var(--size-default);                   /* 32px */
  height: var(--size-default);
}
.nds-button-icon {
  width: var(--size-lg);                        /* 36px */
  height: var(--size-lg);
}
.nds-button-icon-lg {
  width: var(--size-xl);                        /* 40px */
  height: var(--size-xl);
}

/* ── Variantes ─────────────────────────────────────────────────────────────── */

/* Default = primary (filled) */
.nds-button-default {
  background-color: hsl(var(--primary));
  color: hsl(var(--primary-foreground));
  box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
}
.nds-button-default:hover {
  background-color: hsl(var(--primary) / 0.9);
}
.nds-button-default[aria-pressed="true"] {
  background-color: hsl(var(--primary) / 0.9);
}

/* Secondary */
.nds-button-secondary {
  background-color: hsl(var(--secondary));
  color: hsl(var(--secondary-foreground));
  box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
}
.nds-button-secondary:hover,
.nds-button-secondary[aria-pressed="true"] {
  background-color: hsl(var(--secondary) / 0.8);
}

/* Outline */
.nds-button-outline {
  border: 1px solid hsl(var(--border));
  background-color: hsl(var(--background));
  color: hsl(var(--foreground));
  box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
}
.nds-button-outline:hover,
.nds-button-outline[aria-pressed="true"],
.nds-button-outline[aria-expanded="true"] {
  background-color: hsl(var(--accent));
  color: hsl(var(--accent-foreground));
}
/* A linha `border-color: hsl(var(--input))` foi REMOVIDA daqui: era residuo de
 * vocabulario do shadcn sobre a borda que a regra base ja aplica, e dizia que o
 * botao pega emprestada a borda de um input, o que nao e o caso. Na epoca os
 * dois tokens tinham o MESMO valor e a remocao nao mudou um pixel; hoje mudaria
 * — --input escureceu ate 3:1 para responder por WCAG 1.4.11 na borda do CAMPO,
 * e --border seguiu em 90% / 15% como linha decorativa. O botao fica com
 * --border, e toggle, toggle-group e button-group foram alinhados a ele.
 *
 * O fundo continua: no escuro o outline ganha uma superficie levemente
 * elevada para nao encostar na pagina. Isso e superficie, entao o token e
 * --muted — mesmo valor, nome honesto. */
.dark .nds-button-outline {
  background-color: hsl(var(--muted) / 0.3);
}
.dark .nds-button-outline:hover,
.dark .nds-button-outline[aria-pressed="true"] {
  background-color: hsl(var(--accent) / 0.5);
}

/* Ghost */
.nds-button-ghost {
  color: hsl(var(--foreground));
}
.nds-button-ghost:hover,
.nds-button-ghost[aria-pressed="true"],
.nds-button-ghost[aria-expanded="true"] {
  background-color: hsl(var(--accent));
  color: hsl(var(--accent-foreground));
}
.dark .nds-button-ghost:hover,
.dark .nds-button-ghost[aria-pressed="true"] {
  background-color: hsl(var(--accent) / 0.5);
}

/* Link */
.nds-button-link {
  padding: 0;
  background: transparent;
  color: hsl(var(--primary));
  text-underline-offset: 4px;
}
.nds-button-link:hover,
.nds-button-link[aria-pressed="true"] {
  text-decoration: underline;
}

/* Destructive (soft style, alinhada ao restante do projeto) */
.nds-button-destructive {
  background-color: hsl(var(--destructive) / 0.1);
  color: hsl(var(--destructive));
  box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
}
.nds-button-destructive:hover,
.nds-button-destructive[aria-pressed="true"] {
  background-color: hsl(var(--destructive) / 0.15);
}
.nds-button-destructive:focus-visible {
  box-shadow: 0 0 0 2px hsl(var(--background)), 0 0 0 5px hsl(var(--destructive) / 0.4);
}
.dark .nds-button-destructive {
  background-color: hsl(var(--destructive) / 0.15);
}
.dark .nds-button-destructive:hover {
  background-color: hsl(var(--destructive) / 0.25);
}

/* ── Spin (loading) ─────────────────────────────────────────────────────────── */
/* `@keyframes nds-spin` mora em `utilities.css` — nome de keyframes é global,
 * e defini-lo aqui criava um gêmeo que o último import sobrescrevia calado. */
.nds-spin {
  animation: nds-spin 1s linear infinite;
}

/* ── Feedback de ponteiro ───────────────────────────────────────────────────
 * Escala em hover e em press — o gesto responde antes de o estado mudar.
 * Nenhum estado depende só disso: hover também muda cor, e o press é
 * confirmado pelo próprio clique.
 *
 * `:active` vem DEPOIS de `:hover` de propósito: durante o clique o elemento
 * casa com as duas regras, mesma especificidade, e a última é a que vale.
 */
.nds-button:hover:not(:disabled):not([data-disabled]):not([aria-disabled="true"]) {
  transform: scale(1.05);
}
.nds-button:active:not(:disabled):not([data-disabled]):not([aria-disabled="true"]) {
  transform: scale(0.95);
}

/* ── Animação reduzida ─────────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .nds-button:hover:not(:disabled):not([data-disabled]):not([aria-disabled="true"]),
  .nds-button:active:not(:disabled):not([data-disabled]):not([aria-disabled="true"]) {
    transform: none;
  }
  .nds-button {
    transition: none;
  }
  .nds-spin {
    animation: none;
  }
}
